// mutex, coalesce with adjacent free neighbors (within the arena), then
// insert into the per-arena explicit free list. #include "vmlib.h"
#include "vm.h" #include <pthread.h>
#include <stddef.h>
#include <stdint.h> #define HEADER_BYTES 8u #define N_ARENAS 16 #define FREELIST_NIL 0xFFFFFFFFu typedef struct { char *start; char *end; uint32_t head_off; pthread_mutex_t mutex; char pad[64];
} arena_t; extern arena_t g_arenas[N_ARENAS];
extern int vmlib_arena_for(void *addr); static inline struct block_header *blk_footer(struct block_header *h, uint32_t sz) { return (struct block_header *)((char *)h + sz - sizeof(struct block_header));
}
static inline struct block_header *blk_next_h(struct block_header *h, uint32_t sz) { return (struct block_header *)((char *)h + sz);
} static inline uint32_t *fl_prev_slot(struct block_header *h) { return (uint32_t *)((char *)h + 4);
}
static inline uint32_t *fl_next_slot(struct block_header *h) { return (uint32_t *)((char *)h + 8);
}
static inline uint32_t blk_to_off(void *base, struct block_header *h) { return (uint32_t)((char *)h - (char *)base);
}
static inline struct block_header *off_to_blk(void *base, uint32_t off) { if (off == FREELIST_NIL) return NULL; return (struct block_header *)((char *)base + off);
} static inline void fl_push(arena_t *ar, struct block_header *h) { void *base = heapstart; uint32_t off = blk_to_off(base, h); uint32_t old_head = ar->head_off; *fl_prev_slot(h) = FREELIST_NIL; *fl_next_slot(h) = old_head; if (old_head != FREELIST_NIL) { struct block_header *oh = off_to_blk(base, old_head); *fl_prev_slot(oh) = off; } ar->head_off = off;
} static inline void fl_remove(arena_t *ar, struct block_header *h) { void *base = heapstart; uint32_t prev = *fl_prev_slot(h); uint32_t next = *fl_next_slot(h); if (prev == FREELIST_NIL) { ar->head_off = next; } else { struct block_header *ph = off_to_blk(base, prev); *fl_next_slot(ph) = next; } if (next != FREELIST_NIL) { struct block_header *nh = off_to_blk(base, next); *fl_prev_slot(nh) = prev; }
} void vmfree(void *ptr) { if (ptr == NULL) return; if (heapstart == NULL) return; int idx = vmlib_arena_for(ptr); if (idx < 0) return; arena_t *ar = &g_arenas[idx]; pthread_mutex_lock(&ar->mutex); struct block_header *h = (struct block_header *)((char *)ptr - HEADER_BYTES); uint32_t ss = h->size_status; if (!blk_busy(ss)) { pthread_mutex_unlock(&ar->mutex); return; } uint32_t sz = blk_size(ss); uint32_t prev_busy_bit = ss & PREV_BUSY_MASK; // ---- Coalesce with next if next is free and within this arena ---- struct block_header *nxt = blk_next_h(h, sz); if ((char *)nxt < ar->end) { uint32_t nxt_ss = nxt->size_status; uint32_t nxt_sz = blk_size(nxt_ss); if (nxt_sz != 0 && !blk_busy(nxt_ss)) { // Remove next from free list, then merge sizes. fl_remove(ar, nxt); sz += nxt_sz; } } // ---- Coalesce with prev if prev is free (and within arena) ---- if (!prev_busy_bit && (char *)h > ar->start) { struct block_header *prev_foot = (struct block_header *)((char *)h - sizeof(struct block_header)); uint32_t prev_sz = blk_size(prev_foot->size_status); struct block_header *prev_h = (struct block_header *)((char *)h - prev_sz); prev_busy_bit = prev_h->size_status & PREV_BUSY_MASK; // Remove prev from free list before merging. fl_remove(ar, prev_h); h = prev_h; sz += prev_sz; } // Write merged free block. h->size_status = sz | prev_busy_bit; // BUSY=0 struct block_header *foot = blk_footer(h, sz); foot->size_status = h->size_status; // Update PREV_BUSY of the block following the merged free block. struct block_header *after = blk_next_h(h, sz); after->size_status &= ~PREV_BUSY_MASK; if (blk_size(after->size_status) != 0 && !blk_busy(after->size_status)) { struct block_header *af = blk_footer(after, blk_size(after->size_status)); af->size_status = after->size_status; } // Push merged block to head of free list. fl_push(ar, h); pthread_mutex_unlock(&ar->mutex);
